%[text] # Tune CLLC Resonant Converter
%[text] This script plots the frequency response of the CLLC converter from a time-domain simulation and estimates its transfer function, which you use to design the compensator.
%[text] `CLLCResonantConverterControllerDesign` describes the controller options and the design of the voltage loop.
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] ## Load CLLC Converter Parameters
% Set the CLLC converter plant parameters
  %[control:button:30c3]{"position":[1,2]}
% The defaults load only when a variable this script reads is absent, so running EstimateCLLCConverterResonantTankParameters first is enough.
if ~all([exist('CLLCSpec','var') exist('CLLCDesign','var') exist('frequencyRange','var')])
   CLLCConverterDefaultInputParameters;
end
%[text] ## Frequency Response of the CLLC Converter
%[text] To estimate the frequency response of the CLLC converter, use Simulink® Control Design™ to inject a sinestream disturbance into the switching frequency of the Simscape™ model `EstimateCLLCPlantFrequencyResponse`.
%[text] To open the frequency response model, enter this command in the MATLAB® Command Window:
%[text] ```matlabCodeExample
%[text] open_system("EstimateCLLCPlantFrequencyResponse");
%[text] ```
%[text] To estimate the transfer function of the CLLC converter, follow these steps:
%[text] 1. **Verify Model Parameters:** Check that the `EstimateCLLCPlantFrequencyResponse` model has the required parameters.
%[text] 2. **Set Linearization Parameters:** Set the linearization parameters, including `switchingFrequency` and the disturbance `frequencyVector`.
%[text] 3. **Configure Simulation Periods:** For each frequency in `frequencyVector`, set enough periods for the circuit to reach steady state.
%[text] 4. **Select Disturbance Amplitude:** Choose a per-unit disturbance amplitude large enough to measure and small enough to keep the response linear.
%[text] 5. **Verify Steady-State Operation:** For each frequency, check in the plot that the converter reaches steady state. If it does not, increase the settling period.
%[text] 6. **Plot Frequency Response:** To plot the frequency response (Bode plot), run the `plotCLLCFrequencyResponse` MATLAB® script.
%[text] 7. **Estimate Transfer Function, Poles, and Zeros:** To estimate the transfer function, poles, and zeros from the CLLC frequency response, run the `getCLLCPlantPolesAndZeros` MATLAB function. \
%%
  %[control:button:9d74]{"position":[1,2]}
% Frequency response model name
freqRespModelName = "EstimateCLLCPlantFrequencyResponse";

% Operating point for linearization
switchingFrequency = simscape.Value(100e3, "Hz");      % Linearization switching frequency
inputVoltage      = simscape.Value(380, "V");          % Input DC voltage
Rload             = simscape.Value(20.6, "Ohm");       % Output load resistance
steadyStateTime   = simscape.Value(0.052, "s");         % Time to reach steady state at switching frequency

% Sinestream disturbance input parameters
sinestreamStartFreq = simscape.Value(100, "Hz");       % Start frequency of the sinestream disturbance
sinestreamEndFreq   = simscape.Value(71e3, "Hz");      % End frequency of the sinestream disturbance
numFreqPoints       = 30;                              % Number of frequency points in logspace

% Generate frequency vector
frequencyVector = simscape.Value( ...
    linspace(sinestreamStartFreq.value, sinestreamEndFreq.value, numFreqPoints), ...
    "Hz");

% Calculate number of periods for each frequency
numberPeriod = ceil(frequencyVector.value * steadyStateTime.value);

% Sinestream disturbance magnitude (per-unit of resonant frequency)
sinestreamMagnitude = 0.07; % pu

% Estimate frequency response of the plant at the switching frequency
PlotCLLCFrequencyResponse; %[output:58807e90] %[output:379f322c]
%%
%[text] ## CLLC Converter Transfer Function
%[text] This function returns the transfer function from the switching frequency to the output voltage, and its poles and zeros.
  %[control:button:4e69]{"position":[1,2]}
systemModel = getCLLCPlantPolesAndZeros(systemFreqRes,numPole=2,numZero=1); %[output:6ed404ec]
%[text] ## CLLC Compensator Design
%[text] This design solution uses a compensator with two zeros and two poles (2P2Z). One pole is an integrator that removes the steady-state error, and the other cancels the plant zero. The two zeros cancel the plant complex conjugate poles to improve stability and transient response.
CLLCCompensator = getCompensatorPolesAndZeros(systemModel,Domain="All",SamplingTime=1e-7); %[output:66ef7bff]
%[text] ## CLLC Compensator Integrator and Voltage Controlled Oscillator Parameters 
%[text] To set the performance of the CLLC converter voltage controller, tune the integrator gain of the 2P2Z compensator and the voltage-controlled oscillator (VCO) gain.
CLLCCompensator.Ki = 1; % Integrator gain
CLLCCompensator.constantVCOGain = 1; % Voltage controlled oscillator gain (Volt/perunit frequency)
CLLCCompensator.resonantFrequency = CLLCSpec.resonantFrequency.value; % Resonant frequency (Hz)
% One controller serves both power-flow directions, so its frequency limits span the operating
% region reported for each.
[minOperatingFrequency, maxOperatingFrequency] = getCLLCOperatingFrequencyRange(frequencyRange);
CLLCCompensator.minPUfrequency = minOperatingFrequency/CLLCSpec.resonantFrequency.value; % Minimum operating frequency (pu)
CLLCCompensator.maxPUfrequency = maxOperatingFrequency/CLLCSpec.resonantFrequency.value; % Maximum operating frequency (pu)
CLLCCompensator.deadTime = CLLCDesign.deadTime;
CLLCController.vcoGainVec = [1,1.2]; % Voltage controlled oscillator gain vector (Volt/perunit frequency)
CLLCCompensator.SRCurrentThreshold = 0.5; % A
CLLCCompensator.SRBandwidth = 300e3; % Hz

%%
%[text] ## PI Based CLLC Current Controller Parameters
%[text] For narrow input and output voltage ranges, you can regulate the CLLC converter with a PI controller and a suitable VCO gain.
CLLCController.Kp = 3.5; % Proportional controller parameter
CLLCController.Ki = 5; % Integral controller parameter
CLLCController.Kd = 0; % Derivative controller parameter
CLLCController.TsCurrent = 1e-6; % Sample time (s)
%%
%[text] ## PI Based Outer CLLC Voltage Controller Parameters
%[text] You can use a PI controller for the CLLC outer voltage loop.
CLLCController.Kpv = 11; % Proportional controller parameter
CLLCController.Kiv = 5500; % Integral controller parameter
CLLCController.TsVoltage = 1e-6; % Sample time (s)
